// Initialize inotify instance with flags
int ifd = inotify_init1(IN_NONBLOCK | IN_CLOEXEC);

// Equivalent to inotify_init()
int ifd_simple = inotify_init1(0);

if (ifd < 0) {
    // Check errno for specific failures:
    // EINVAL: Invalid flags
    // EMFILE: Descriptor limit reached
    perror("inotify_init1");
}

// Successful initialization returns a file descriptor (ifd >= 0)
// Must be closed via close(ifd)
